function init () {

    checked_cocki();
}

function openNav() {
    let hamburger = document.querySelector(".hamburg");
    let nav = document.querySelector("nav");

    if (hamburger.classList.toggle("checked")) {
        nav.style.display = "flex";
    } else {
        nav.style.display = "none";
    }
}


function checked_cocki() {
    let cockies = document.getElementById("cockie-container-id");
    if (document.cookie) {
        console.log(cockies.style.display = "none");
    } else {
        console.log(cockies.style.display = "block");
    }
}

let cockies_button = document.getElementById("cockie-button-ok");

cockies_button.addEventListener("click", function () {
    let cockies = document.getElementById("cockie-container-id");


    if (document.cookie = "cockies = accepted") {
        console.log(cockies.style.display = "none");
    } else {
        console.log(cockies.style.display = "block");
    }
});

let cockies_button_loeschen = document.getElementById("cockie-button-cancel");

cockies_button_loeschen.addEventListener("click", function () {

    let cockies = document.getElementById("cockie-container-id");
    if (document.cookie = "cockies = accepted") {
        let n = "cockies";
        document.cookie = n + '=; expires=Thu, 01-Jan-70 00:00:01 GMT;';
        localStorage.cookie.removeItem("cockie");
        cockies.style.display = "block";
        console.log("Cockie wurde gelöscht");

    };
});
